<?php namespace App\Http\Controllers\Purchasing; use App\Http\Controllers\Controller; use App\Models\Supplier; use Illuminate\Http\Request; class SupplierController extends Controller { public function index(){return view('purchasing.suppliers.index',['suppliers'=>Supplier::withCount('purchases')->latest()->paginate(15)]);} public function store(Request $r){$d=$r->validate(['name'=>['required','string','max:150'],'code'=>['required','string','max:40','alpha_dash','unique:suppliers,code'],'email'=>['nullable','email','max:150'],'phone'=>['nullable','string','max:40'],'address'=>['nullable','string','max:1000'],'tax_id'=>['nullable','string','max:80']]);$s=Supplier::create($d+['is_active'=>true]);app(\App\Services\AuditLogger::class)->record($r,'purchasing.supplier_created','success',['supplier_id'=>$s->id,'code'=>$s->code]);return back()->with('success','Supplier created.');} }
